Translate("ruRU", "shadowsong-shrine", {
	title = "Святилище Песни Теней",
	sections = {
		{
			title = "Обзор",
			text = [=[Святилище Песни Теней — руины на западе Азшары, к северо-востоку от Заставы Талрендис. Здесь обитают призраки. Привидения высокорожденных и малые личи скользят среди его камней, все еще алчущие тайной магии, которая их погубила. Духи тревожат все народы без разбора, а такая жажда, как у них, говорят, притягивает взор {link:burning-legion}Пылающего Легиона{/link}. {link:sentinels}Часовые{/link} просили, чтобы их освободили от этого мира. Неподалеку бродит призрак более мрачный — тот, что носит имя капитана королевы Азшары.]=],
		},
	},
})

Translate("ruRU", "ravencrest-monument", {
	title = "Памятник Черному Ворону",
	sections = {
		{
			title = "Обзор",
			text = [=[На утесах южной оконечности Азшары, над открытым морем, лежат останки колоссальной статуи древних эльфов. Стоят до сих пор только ее ноги. Остальное лежит вокруг них в обломках или упало в волны. Она носит имя дома Гребня Ворона, но ни одна летопись не сообщает, в чью честь она была воздвигнута и когда. Теперь среди обломков бродят наги Злобного Хлыста. Добраться до нее можно только по суше, через мост.]=],
		},
	},
})

Translate("ruRU", "southridge-beach", {
	title = "Южный пляж",
	sections = {
		{
			title = "Обзор",
			text = [=[Южный пляж лежит на южном побережье Азшары, ниже лесов, где несет свой дозор синий дракон {link:azuregos}Азурегос{/link}. Сюда в поисках безопасной стоянки пришел корабль {i}Разведчик горизонта{/i} под началом капитана Ванессы Белтис. Не прошло и часа после заката, как на ее команду напали наги. Уцелевшие заняли оборону в долине над пляжем и ждут там до сих пор, зная, что наги вернутся. Некоторые из ее пассажиров прибыли в Азшару по собственным делам.]=],
		},
	},
})

Translate("ruRU", "blackmaw-hold", {
	title = "Крепость Чернобрюхов",
	sections = {
		{
			title = "Обзор",
			text = [=[На севере Азшары стоят великие ворота {link:furbolgs}фурболг{/link}ов. Сколько помнит себя любой житель {link:kalimdor}Калимдор{/link}а, они были закрыты, а их стража прогоняла всякого чужака, который подходил близко. За ними лежит Крепость Чернобрюхов, {link:ogres}огр{/link}омный город фурболгов, вырубленный глубоко в горе. Его жители борются с порчей, которая зашевелилась в его глубинах. Говорят, что его туннели уходят еще ниже, в места более древние, чем сам город.]=],
		},
	},
})

Translate("ruRU", "loramus-thalipedes", {
	title = "Лорамус Талипедес",
	subtitle = "Охотник на демонов из Азшары",
	found = "Маленький остров на юге Залива Бурь",
	hint = [=[Обыщите острова Залива Бурь в поисках того, кто охотится на демонов.]=],
	allegiance = "Никому, кроме собственной охоты",
	aliases = { "Лорамус" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лорамус Талипедес — охотник на демонов, который живет один на острове в Заливе Бурь. Его стерегут три гончие Скверны: Райтаф, Шахиар и {link:apothecary-zamah}Зама{/link}н. Он не терпит, когда его прерывают. И все же он знает о владыках {link:burning-legion}Пылающего Легиона{/link} в этом мире больше, чем любой мудрец королевств, и поможет всякому, кто достаточно безрассуден, чтобы на них охотиться.]=],
		},
		{
			title = "Значение",
			text = [=[Лорамус — единственный, кто знает, как ранить демона {link:razelikh-the-defiler}Разелих{/link}а Осквернителя. Он знает историю отступления владыки {link:lord-kazzak}Каззак{/link}а в {link:the-tainted-scar}Гниющий шрам{/link}, договор, который связывает трех капитанов Осквернителя, и обряд, которым можно узнать истинное имя Осквернителя. Без него войну против владыки демонов {link:blasted-lands}Выжженных земель{/link} нельзя было бы вести вовсе.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он проводит ритуал просветления, чтобы узнать, как можно сломать защиту Осквернителя.
