			title = "Повесть об Осквернителе",
			hint = "Сядьте и выслушайте повесть охотника на демонов.",
			text = [=[Тех, кого прислал {link:fallen-hero-of-the-horde}Павший герой Орды{/link}, Лорамус встречает неприветливо. Он все равно рассказывает свою повесть и не любит, когда его перебивают. Когда Легион был разбит, {link:lord-kazzak}Каззак{/link} был отброшен в {link:the-tainted-scar}Гниющий шрам{/link}, а {link:razelikh-the-defiler}Разелих{/link}, самый грозный из его помощников, был послан удерживать для него эту землю. На его сторону встали {link:ogres}огр{/link}ы и сектанты, а также те трое, что ныне хранят его амулет.]=],
		},
		{
			title = "Имя зверя",
			hint = "Узнайте истинное имя демона у владыки макрур.",
			text = [=[Только оружие, несущее истинное имя демона, может ранить его и всех, кто ему служит. Сам Лорамус узнать это имя не мог. Он послал своего помощника в {link:temple-of-arkkoran}Храм Арккоран{/link}, и ценой владыки макрур была кровь. Имя вернулось вместе с закалочным составом, добытым из голов зверя: {link:razelikh-the-defiler}Рак'лих{/link}.]=],
		},
		{
			title = "Погибель Скверны",
			hint = [=[Отнесите груз охотника на демонов кузнецу Мифрилового ордена.]=],
			text = [=[С азшаритом из южных холмов и закалочным составом владыки {link:lord-arkkoroc}Арккорок{/link}а материалы были готовы. Лорамус отослал их на юг, в {link:stranglethorn-vale}Тернистую долину{/link}, кузнецу {link:galvan-the-ancient}Галван{/link}у Древнему. Старый кузнец уже много лет не слышал имени охотника на демонов.]=],
