Translate("ruRU", "archmage-xylem", {
	title = "Верховный маг Ксилем",
	subtitle = "Хозяин башни в холмах",
	found = "Его башня на утесах над западной Азшарой",
	hint = [=[Найдите верховного мага, чья башня смотрит на Азшару. Его слуга ждет внизу.]=],
	allegiance = "Собственные изыскания",
	aliases = { "Ксилем" },
	sections = {
		{
			title = "Обзор",
			text = [=[Верховный маг Ксилем — человек, маг, который поселился в башне высоко в холмах над Азшарой. Гости должны сперва найти его слугу {link:sanath-lim-yo}Санат{/link}а Лим-йо, который магией переносит их наверх, в башню. Ксилем горд, холоден и очень могуществен. Он человек, как говорит {link:jediga}Джедига{/link} из {link:valormok}Храбростан{/link}а, но ведет себя не так, как любой человек, какого она встречала.]=],
		},
		{
			title = "Значение",
			text = [=[Ксилем пришел в Азшару по той же причине, что и все остальные: ради ее магии. Он скупает знания высокорожденных, собирает зачарованные кораллы залива и следит за этой землей через заклинания ясновидения. Даже лорд разбойников {link:lord-jorach-ravenholdt}Джорах Черный Ворон{/link} обращается к нему, когда нужно сломать чары.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он платит торговке Джедиге за табличку Саэл'хая из Руин {link:ruins-of-eldarath}Эльдарат{/link}а.
• Он послал ученика выменять у эльфов крови их сверкающую пыль, и эльфы крови убили ученика.
• Он трудится над тем, чтобы снять чары с запечатанной лазурной сумки для лорда Черного Ворона.
• Он посылает охотника за полководцем {link:warlord-krellian}Креллиан{/link}ом и за радужной раковиной, которой жаждет наг.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не сообщает, откуда пришел Ксилем, почему он выбрал Азшару и что он намерен делать со всем, что собирает.]=],
		},
	},
	chapters = {
		{
			title = "Табличка Саэл'хая",
			hint = [=[Доставьте верховному магу последнюю из табличек, которые продает Джедига.]=],
			text = [=[{link:jediga}Джедига{/link} предупреждала, что Ксилем — самый опасный из всех ее покупателей. Он взял табличку и заплатил ровно столько, сколько обещал. Это удивило ее больше, чем удивило бы любое предательство.]=],
		},
		{
			title = "Старый заклятый враг",
			hint = "Отомстите за ученика верховного мага в затонувшем храме.",
			text = [=[Много лет назад зеленый дракон {link:morphaz}Морфаз{/link} напал на мага из засады и проглотил одного из его учеников целиком. Ксилем не скорбел об ученике. Он скорбел об осколке тайной магии, который тот носил при себе. Когда осколок вырезали из брюха дракона в {link:temple-of-atal-hakkar}Храме Атал'Хаккара{/link}, он успел вырасти вместе с силой дракона. С ним к верховному магу вернулось все его искусство.]=],
		},
	},
	mentions = {
		{ text = "Доставка верховному магу Ксилему" },
		{ text = "Плата от мага Ксилема для торговки Джедиги" },
		{ text = "Зашифрованные фрагменты" },
		{ text = "Лазурный ключ" },
		{ text = "Волшебная пыль" },
		{ text = "Коралл сирены" },
		{ text = "Уничтожить дракона {link:morphaz}Морфаз{/link}а" },
		{ text = "{link:warlord-krellian}Полководец Креллиан{/link}" },
		{ text = "{link:great-sundering}Раскол{/link}отая магия" },
	},
	bonds = {
		{ id = "sanath-lim-yo", name = "Санат Лим-йо", note = "его слуга" },
		{ id = "jediga", name = "Джедига", note = "продала ему табличку" },
		{ id = "lord-jorach-ravenholdt", name = "Лорд Джорах Черный Ворон", note = "попросил его об услуге" },
		{ id = "morphaz", name = "Морфаз", note = "его старый заклятый враг" },
		{ id = "warlord-krellian", name = "Полководец Креллиан", note = "владеет раковиной, которая ему нужна" },
		{ id = "magus-rimtori", name = "Маг Римтори", note = "ее народ убил его ученика" },
	},
})

Translate("ruRU", "sanath-lim-yo", {
