	found = "У подножия холмов под башней мага Ксилема",
	hint = [=[Найдите грубого слугу, который стережет путь к башне верховного мага.]=],
	allegiance = "Верховный маг Ксилем",
	aliases = { "Санат" },
	sections = {
		{
			title = "Обзор",
			text = [=[Санат Лим-йо стережет путь к башне верховного мага {link:archmage-xylem}Ксилем{/link}а. {link:jediga}Джедига{/link} называет его телохранителем мага. Когда-то он мог требовать что угодно от тех, кто приходил искать его господина. Теперь Ксилем велел ему отправлять наверх всякого, кто попросит, и это его злит. Он утешается тем, что высмеивает одежду и лица гостей, но даже это ему наскучило.]=],
		},
		{
			title = "Значение",
			text = [=[Всякая дорога к верховному магу проходит через его слугу. Нирилл, ученик верховного мага, надеется, что когда-нибудь он научится хоть каким-то манерам.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он магией отправляет гостей наверх, в башню.
• Делая это, он над ними насмехается.]=],
		},
	},
	mentions = {
		{ text = "Встреча с господином" },
		{ text = "Обратный путь" },
	},
	bonds = {
		{ id = "archmage-xylem", name = "Верховный маг Ксилем", note = "его господин" },
	},
})

